import json,collections,re,hashlib
from pathlib import Path
D=Path(__file__).resolve().parents[2]/'docs/einsamkeit'
rows=[json.loads(l) for l in (D/'bestandsaufnahme.jsonl').read_text().splitlines()];byid={r['id']:r for r in rows}
issues=[]
def issue(id,title,refs,question,needed):
 refs=refs.split(',');assert all(r in byid for r in refs)
 issues.append({'id':id,'thema':title,'quellzeilen':refs,'zugeordneteThemen':list(dict.fromkeys(t for ref in refs for t in byid[ref]['zuordnungen'])),'status':'primaerquellenpruefung_offen','ungeklaert':question,'erforderlich':needed,'fachlicheZuordnungOffen':False})
issue('P01','Stiftungsname und koordinierende Stelle','B1-L137,B2-L549,B3-L13,B4-L17','Die Aufbereitungen enthalten abweichende Stiftungsbezeichnungen; Identität und offizielle Schreibweise sind nicht belegt.','Offizielle Selbstdarstellung/Impressum und Originalaufzeichnung abgleichen; keine der Transkriptionsfassungen ungeprüft auswählen.')
issue('P02','Personennamen, Funktionen und Kontaktrollen','B1-L138,B1-L139,B1-L149,B2-L550,B3-L27,B4-L434','Schreibweisen und Funktionen insbesondere von Cornelia Springer-Foart, Axel Weber und Svante Tiedemann sind nur aus Aufbereitungen erschlossen.','Originalpräsentation, Veranstalterangaben und Rollen zum Veranstaltungszeitpunkt prüfen; keine privaten Kontaktdaten ergänzen.')
issue('P03','Kompetenznetz: KNE/KME','B1-L147,B3-L114,B3-L117','B1 nennt KNE, B3 KME. Die abweichende Abkürzung bleibt im Original erhalten.','Offizielle Bezeichnung und institutionelle Zuordnung anhand der Originalquelle prüfen; keine stille Korrektur der Quelltexte.')
issue('P04','Preisname und Preisjahrgänge','B1-L236,B1-L237,B1-L238,B2-L78,B2-L80,B2-L492,B3-L129,B3-L382,B4-L191,B4-L192,B4-L193,B4-L194','Die Texte nennen Gemeinsamkeitspreis bzw. Gemeinschaftspreis und Preis-/Verleihungsangaben für 2026 und 2027. Eine eindeutige Ereigniszuordnung ist damit noch nicht gesichert.','Offiziellen Preisnamen, Ausschreibungen und jeweils zugehörige Verleihung separat nach Jahrgang prüfen. Jahresangaben nicht zu einem einzigen Termin verschmelzen.')
issue('P05','26. November und Veranstaltungsreihe','B1-L228,B2-L482,B2-L554,B3-L377,B4-L215,B4-L1173','B2 bezeichnet die Jahresangabe ausdrücklich als widersprüchlich; andere Fassungen nennen 2026.','Originaleinladung und Datum des Auftakts prüfen; Bielefeld, Veranstaltungsreihe und Kooperationspartner eindeutig zuordnen.')
issue('P06','Strategietermine 2027 und 3. Mai','B1-L229,B1-L230,B2-L256,B2-L268,B3-L378,B3-L379,B3-L380,B4-L323,B4-L1181,B4-L1185','Terminstatus, Jahr und Funktion einzelner Treffen sind teils vorläufig; September bezeichnet je nach Text Forum bzw. Zusammenführung.','Offizielle Programme für 19. Februar, 3. Mai und September getrennt prüfen. Planung nicht als stattgefundenes Ereignis ausgeben.')
issue('P07','Bundeskonferenz, Aktionswoche und Barometer','B1-L234,B2-L87,B2-L90,B4-L201,B4-L202,B4-L204,B4-L206','Teilweise fehlt das Jahr, teilweise handelt es sich um Ankündigungen; Erscheinungsstand wissenschaftlicher Publikationen ist nicht geprüft.','Offizielle Termin-/Publikationsangaben samt Planungsstand und Abrufdatum ermitteln.')
issue('P08','Krisennetz','B1-L232,B4-L1175','Der genannte Akteur und weitere Veranstaltungstermin sind nicht eindeutig identifiziert.','Originalaufnahme bzw. Veranstalter nach genauer Bezeichnung und Einladung prüfen; fachlich bei Veranstaltungen belassen, keinen Träger erfinden.')
issue('P09','Miller & Willi','B4-L388','Der Projektname ist im Bericht ausdrücklich als überprüfungsbedürftig markiert.','Originalbezeichnung, Projektträger und beschriebenes Modell identifizieren; keine vermeintliche Korrektur oder Projektadresse erfinden.')
issue('P10','SAIWIR und Angebotsdatenbank','B4-L45,B4-L664,B4-L944,B4-L1363','Name/Rechtsstatus des Partners sowie tatsächlicher Entwicklungs- und Betriebsstand der Datenbank sind ungeprüft.','Offizielle Projekt-/Trägerangaben und Stand zum Auftakt prüfen. Nicht mit einer Funktion dieser Bürgerplattform gleichsetzen.')
issue('P11','Klönschnacker und HVV','B4-L859,B4-L860,B4-L861','Projektbezeichnung, Ausgestaltung und aktueller Stand sind im Bericht offen.','Genaues Projekt und belegten Kooperationsstatus ermitteln; Nennung ist kein nachgewiesener Vertrag oder aktuelles Angebot.')
issue('P12','Hamburger Allianzmitgliedschaft und politische Ausgangslage','B1-L142,B1-L143,B2-L553,B3-L74,B3-L75,B4-L145,B4-L146,B4-L173,B4-L176','Behauptungen zur Landesmitgliedschaft, zu Einzelorganisationen und zu einem fehlenden Aktionsplan sind zeitgebundene Veranstaltungsangaben.','Amtlichen Stand und Mitgliederliste zum relevanten Zeitpunkt prüfen; Land und einzelne Organisationen getrennt behandeln. Wortlaut der behaupteten Sonderstellung nicht ungeprüft bestätigen.')
issue('P13','Historische Zählung und unterschiedliche Einschätzungen','B4-L461,B4-L462,B4-L464,B4-L466,B4-L467,B4-L468,B4-L469,B4-L475','Die Zahl 97 ist eine persönliche Bestandsaufnahme. Zur Frage eines Ersatzes verlorener Orte werden unterschiedliche Sichtweisen berichtet; Standorte und Zeiträume sind nicht belegt.','Standortliste, Zeiträume, Betriebsnamen und Primärquellen ermitteln; Widerspruch und Sprecherperspektiven erhalten. Keine amtliche Statistik und kein Kausalnachweis für individuelle Einsamkeit.')
issue('P14','Polnisches Mahlzeitenbeispiel','B1-L82,B2-L346,B4-L523,B4-L526,B4-L527,B4-L528','Ort und Fernsehbeitrag fehlen; Preis, Förderung und Wirkungen beruhen auf einer Erinnerung.','Sendung, Einrichtung, Zeitraum und Finanzierung identifizieren; bis dahin nur als berichtete Anregung erschließen.')
issue('P15','Praxisbeispiele und aktuelle Angebotsdaten','B1-L91,B4-L549,B4-L550,B4-L551,B4-L554,B4-L591,B4-L594,B4-L596','Durchführung, Preise, Öffnungszeiten, Reichweite und wahrgenommene Auslastung sind nicht aktuell verifiziert.','Pottkieker und KulturistenHoch2 getrennt bei den Trägern prüfen; subjektive Auslastungsaussage nicht als Wirksamkeitsstudie verwenden.')
issue('P16','Wissenschaftliche Studien, Messung und Kausalität','B2-L552,B2-L556,B3-L60,B4-L96,B4-L120,B4-L137,B4-L140,B4-L910,B5-L85,B5-L121,B5-L379','Exakte Studien/Fundstellen fehlen teilweise. Medizinische, psychologische, demokratiebezogene und wirtschaftliche Aussagen sind keine durch diese Auswertung verifizierten Ergebnisse.','Originalstudien/Reviews und genaue Expertise ermitteln; Definitionen, Messinstrumente, Populationen, Jahre, Effektgrößen und Grenzen prüfen. Keine Korrelation zu Kausalität umformen; für die Kostenfrage wurde keine Berechnung vorgelegt.')
issue('P17','Sozialraumbeschreibungen und Mobilitätskonzept','B5-L251,B5-L255','B5 nennt amtliche Grundlagen ohne vollständige bibliografische Fundstelle. Die sichtbaren Favicons sind kein Nachweis.','Genaue Titel, Fassungen, Herausgeber, Seiten und tatsächliche Aussagen zu Bergedorf und Vier-/Marschlanden ermitteln.')
issue('P18','Partner, Zusagen und Rollen von Einrichtungen','B3-L258,B4-L795,B4-L851,B4-L853,B4-L854,B4-L1292','Viele Institutionen werden als mögliche Partner genannt. Daraus folgt keine Beteiligungszusage und kein öffentlicher Hilfeauftrag.','Vorschlag, bestehender Kontakt und zugesagte Kooperation trennen; zuständige Institution und mögliche Datenschutz-/Einwilligungsgrenzen separat prüfen.')
issue('P19','Beteiligung, Redaktion, Datenschutz und Organisationsrecht','B1-L133,B1-L134,B5-L307,B5-L347,B5-L349,B5-L481,B5-L483,B5-L487','Vorgeschlagene Kontakt-, Melde-, Moderations-, Gründungs- und Hilfsabläufe sind noch keine geprüften oder aktivierten Leistungen.','Rechtliche, organisatorische, Datenschutz- und Sicherheitsvoraussetzungen im zuständigen späteren Auftrag prüfen. In dieser Auswertung keine neuen Funktionen oder Zusagen ableiten.')
for r in rows:r['offenePrueffragen']=[i['id'] for i in issues if r['id'] in i['quellzeilen']]
(D/'offene-prueffragen.json').write_text(json.dumps(issues,ensure_ascii=False,indent=2)+'\n')
(D/'bestandsaufnahme.jsonl').write_text('\n'.join(json.dumps(r,ensure_ascii=False,separators=(',',':')) for r in rows)+'\n')
# Nur wortgleiche Texte nach Entfernen der Aufzählungsmarke; keine semantische
# Gleichsetzung ähnlicher Aussagen, keine Löschung und kein unabhängiger Beleg.
groups=collections.defaultdict(list)
for r in rows:
 if r['zeilenrolle']=='inhalt':groups[re.sub(r'^(?:- |\d+\\?\. )','',r['original']).strip()].append(r['id'])
exact=[{'vergleichstext':t,'quellzeilen':ids,'regel':'Nur Aufzählungsnummer/-zeichen entfernt; Kontexte und Originale bleiben getrennt.'} for t,ids in groups.items() if len(ids)>1]
(D/'wiederholungen.json').write_text(json.dumps({'wortgleicheGruppen':exact,'hinweis':'Semantisch verwandte Inhalte werden über dieselben bestehenden Themenknoten erschlossen. Nicht wortgleiche Varianten bleiben vollständig erhalten. Keine fünf unabhängigen Bestätigungen aus fünf Aufbereitungen desselben Auftakts ableiten.'},ensure_ascii=False,indent=2)+'\n')
s=json.loads((D/'auswertungsbilanz.json').read_text());s.update(offenePrimaerprueffragen=len(issues),wortgleicheGruppen=len(exact));(D/'auswertungsbilanz.json').write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n')
registry=json.loads((D/'quellenregister.json').read_text());registry['reviewSummary']=s;(D/'quellenregister.json').write_text(json.dumps(registry,ensure_ascii=False,indent=2)+'\n')
# Fachautoren erhalten je Themenknoten Direktfundstellen und den Ober-/Unterkontext.
index=json.loads((D/'artikel-quellenindex.json').read_text())
lines=['# Artikelregister zu den fünf Ausgangsberichten','','Alle Angaben sind redaktionell erschlossen, nicht extern tatsachenverifiziert. Direkte Zuordnungen und zusätzlicher Kontext sind getrennt. Keine Fachartikel erzeugt.','']
for id,n in index.items():
 lines+=['## '+n['conceptNumber']+' '+n['title'],'',f"Themen-ID: `{id}`. Direkt zugeordnete Inhaltszeilen: {len(n['direktZugeordnet'])}; Kontext-/Gliederungszeilen: {len(n['kontext'])}; einschließlich Unterthemen: {len(n['mitUnterthemen'])}.",'']
 for role,key in [('Inhalte','direktZugeordnet'),('Kontext','kontext')]:
  if not n[key]:continue
  lines+=[role+': '+', '.join('`'+ref+'`' for ref in n[key])+'.','']
 lines+=['Originalwortlaut, genaue ursprüngliche Fundstelle, Aussageart, Mehrfachzuordnungen und Prüfbedarf: jeweilige ID in `bestandsaufnahme.jsonl`. Weitere Nachweise: `offene-prueffragen.json`.','']
(D/'artikelregister.md').write_text('\n'.join(lines))
print(json.dumps({'issues':len(issues),'exactGroups':len(exact),'exactOccurrences':sum(len(g['quellzeilen']) for g in exact),'rawFieldsSha256':hashlib.sha256(json.dumps([[r[k] for k in ['id','datei','fundstelle','quellabschnitt','original']] for r in rows],ensure_ascii=False,separators=(',',':')).encode()).hexdigest()}))
